"""Flight Recorder weak-verifier overfit pilot (curriculum warm-start) - baked-in.

Coder-1.5B-Instruct, NO seeding, onset_mode=oracle, ENGINEERED curriculum warm-start so a
high->low oracle turn exists. Prints [fr] step/visible/oracle live for monitoring. The turn
is engineered (budget sizing), NOT evidence of emergence. GATE 2: hard timeout caps cost.
"""

import base64, io, sys, tarfile

_PKG_B64 = (
''
)

def _unpack() -> None:
    data = base64.b64decode(_PKG_B64)
    with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as tf:
        tf.extractall("/tmp/fr")
    sys.path.insert(0, "/tmp/fr")

_unpack()
from flightrecorder.repro.trl_grpo_qwen import main  # noqa: E402
sys.exit(main([
    "--scale", "pilot", "--reward-mode", "gameable", "--integrity-report",
    "--thresholds", "/tmp/fr/configs/thresholds.yaml",
    "--artifact-dir", "/tmp/fr/runs",
]))
